import base64
import hashlib
import os

def task_func(password, SALT_LENGTH = 32):
    if password is None or password == "":
        raise ValueError("Password must not be None or empty")

    if isinstance(password, str):
        password = password.encode("utf-8")

    salt = os.urandom(SALT_LENGTH)
    hashed_password = hashlib.pbkdf2_hmac(
        "sha256",
        password,
        salt,
        100000,
    )

    return base64.b64encode(salt), base64.b64encode(hashed_password)

import re
import os


def task_func(request):
    if not isinstance(request, str):
        return "HTTP/1.1 400 Bad Request\r\n\r\nInvalid request"

    match = re.match(r"^GET\s+/([^?\s]*)?(?:\?[^\s]*)?\s+HTTP/\d(?:\.\d)?\s*$", request.strip())
    if not match or not match.group(1):
        return "HTTP/1.1 400 Bad Request\r\n\r\nInvalid request"

    filename = match.group(1)
    server_directory = os.path.abspath(os.getcwd())
    file_path = os.path.abspath(os.path.join(server_directory, filename))

    if not file_path.startswith(server_directory + os.sep) or not os.path.isfile(file_path):
        return "HTTP/1.1 404 Not Found\r\n\r\nFile not found"

    try:
        with open(file_path, "r", encoding="utf-8") as file:
            content = file.read()
    except (OSError, UnicodeDecodeError):
        return "HTTP/1.1 404 Not Found\r\n\r\nFile not found"

    content_length = len(content.encode("utf-8"))
    return (
        f"HTTP/1.1 200 OK\r\n"
        f"Content-Length: {content_length}\r\n"
        f"\r\n"
        f"{content}"
    )

