import json
import csv
import os
import base64


def task_func(raw_string, filename, output_dir):
    decoded = base64.b64decode(raw_string)
    data = json.loads(decoded.decode("utf-8"))

    os.makedirs(output_dir, exist_ok=True)
    file_path = os.path.join(output_dir, filename)

    def serialize_value(value):
        if isinstance(value, (dict, list)):
            return json.dumps(value, ensure_ascii=False)
        return value

    with open(file_path, "w", newline="", encoding="utf-8") as csv_file:
        writer = csv.writer(csv_file)

        if isinstance(data, list):
            if data and all(isinstance(item, dict) for item in data):
                fieldnames = []
                for item in data:
                    for key in item:
                        if key not in fieldnames:
                            fieldnames.append(key)

                writer.writerow(fieldnames)
                for item in data:
                    writer.writerow(
                        [serialize_value(item.get(field)) for field in fieldnames]
                    )
            else:
                for row in data:
                    if isinstance(row, list):
                        writer.writerow([serialize_value(value) for value in row])
                    else:
                        writer.writerow([serialize_value(row)])
        elif isinstance(data, dict):
            fieldnames = list(data.keys())
            writer.writerow(fieldnames)
            writer.writerow([serialize_value(data[field]) for field in fieldnames])
        else:
            writer.writerow([serialize_value(data)])

    return file_path

import pandas as pd
import re
import random


def task_func(s: str, seed: int = 0) -> pd.DataFrame:
    products = ["Apple", "Banana", "Orange", "Pear", "Grape"]
    rng = random.Random(seed)
    product_by_code = {}
    rows = []

    for line_number, line in enumerate(s.splitlines(), start=1):
        if not line.strip():
            continue

        parts = re.split(r"\s+", line.strip(), maxsplit=4)
        if len(parts) != 5:
            raise ValueError(
                f"Line {line_number} must contain ID, quantity, code, price, "
                "and description."
            )

        id_value, quantity, code, price, description = (
            part.rstrip() for part in parts
        )

        try:
            id_value = int(id_value)
            quantity = int(quantity)
            price = int(price)
        except ValueError as exc:
            raise ValueError(
                f"Line {line_number} contains a non-integer ID, quantity, or price."
            ) from exc

        if code not in product_by_code:
            product_by_code[code] = rng.choice(products)

        rows.append(
            {
                "ID": id_value,
                "Quantity": quantity,
                "Code": code,
                "Price": price,
                "Product": product_by_code[code],
                "Description": description,
            }
        )

    return pd.DataFrame(
        rows,
        columns=["ID", "Quantity", "Code", "Price", "Product", "Description"],
    )

import itertools
import math
from pandas import Series


def task_func(elements, subset_size, top_n=2):
    if subset_size > len(elements) or subset_size == 0:
        return 1

    subset_sums = [
        sum(subset)
        for subset in itertools.combinations(elements, subset_size)
    ]

    product_of_sums = math.prod(subset_sums)
    top_sums = Series(sorted(subset_sums, reverse=True)[:top_n])

    return product_of_sums, top_sums

import subprocess
import os
import signal
import time


def task_func(process_name: str) -> int:
    if not process_name:
        return 0

    current_pid = os.getpid()
    pids = []

    try:
        if os.name == "nt":
            result = subprocess.run(
                ["tasklist", "/FO", "CSV", "/NH"],
                capture_output=True,
                text=True,
                check=False,
            )
            for line in result.stdout.splitlines():
                fields = line.strip().strip('"').split('","')
                if len(fields) >= 2 and fields[0].casefold() == process_name.casefold():
                    try:
                        pid = int(fields[1])
                        if pid != current_pid:
                            pids.append(pid)
                    except ValueError:
                        continue
        else:
            result = subprocess.run(
                ["ps", "-eo", "pid=,comm="],
                capture_output=True,
                text=True,
                check=False,
            )
            for line in result.stdout.splitlines():
                parts = line.strip().split(None, 1)
                if len(parts) == 2 and parts[1] == process_name:
                    try:
                        pid = int(parts[0])
                        if pid != current_pid:
                            pids.append(pid)
                    except ValueError:
                        continue
    except (OSError, subprocess.SubprocessError):
        return 0

    stopped = 0
    for pid in pids:
        try:
            if os.name == "nt":
                subprocess.run(
                    ["taskkill", "/PID", str(pid), "/T", "/F"],
                    capture_output=True,
                    check=False,
                )
            else:
                os.kill(pid, signal.SIGTERM)
            stopped += 1
        except (OSError, ProcessLookupError):
            continue

    time.sleep(1)
    return stopped

