import os
import shutil
import uuid

# Constants
BACKUP_DIR = '/tmp/backup'


def get_unique_backup_dir():
    return os.path.join(BACKUP_DIR, f"backup_{uuid.uuid4().hex}")


def task_func(directory):
    backup_dir = get_unique_backup_dir()
    errors = []

    if not os.path.isdir(directory):
        return backup_dir, [f"Directory does not exist: {directory}"]

    try:
        os.makedirs(os.path.dirname(backup_dir), exist_ok=True)
        shutil.copytree(directory, backup_dir, symlinks=True)
    except Exception as exc:
        return backup_dir, [f"Backup failed: {exc}"]

    try:
        for entry in os.scandir(directory):
            try:
                if entry.is_dir(follow_symlinks=False):
                    shutil.rmtree(entry.path)
                else:
                    os.unlink(entry.path)
            except Exception as exc:
                errors.append(f"Failed to remove {entry.path}: {exc}")
    except Exception as exc:
        errors.append(f"Failed to clean directory {directory}: {exc}")

    return backup_dir, errors

