import subprocess
import os
import shutil
from glob import glob


def task_func(src_folder, dst_folder):
    failed_files = []

    if not os.path.isdir(src_folder):
        return {
            "success": False,
            "message": f"Source folder does not exist: {src_folder}",
            "failed_files": [src_folder],
        }

    try:
        os.makedirs(dst_folder, exist_ok=True)
    except OSError as exc:
        files = [
            path for path in glob(os.path.join(src_folder, "*"))
            if os.path.isfile(path)
        ]
        return {
            "success": False,
            "message": f"Could not create destination folder: {exc}",
            "failed_files": [os.path.basename(path) for path in files],
        }

    files = [
        path for path in glob(os.path.join(src_folder, "*"))
        if os.path.isfile(path)
    ]

    for source_path in files:
        filename = os.path.basename(source_path)
        destination_path = os.path.join(dst_folder, filename + ".gz")
        temporary_path = destination_path + ".part"

        try:
            with open(temporary_path, "wb") as output_file:
                process = subprocess.Popen(
                    ["gzip", "-c", source_path],
                    stdout=output_file,
                    stderr=subprocess.PIPE,
                )
                _, stderr = process.communicate()

            if process.returncode != 0:
                raise RuntimeError(
                    stderr.decode(errors="replace").strip()
                    or f"gzip exited with code {process.returncode}"
                )

            shutil.move(temporary_path, destination_path)
        except (OSError, subprocess.SubprocessError, RuntimeError) as exc:
            failed_files.append(filename)
            try:
                if os.path.exists(temporary_path):
                    os.remove(temporary_path)
            except OSError:
                pass

    success = not failed_files
    if success:
        message = f"Successfully compressed and moved {len(files)} file(s)."
    else:
        message = (
            f"Compressed and moved {len(files) - len(failed_files)} of "
            f"{len(files)} file(s); {len(failed_files)} failed."
        )

    return {
        "success": success,
        "message": message,
        "failed_files": failed_files,
    }

