import numpy as np
import random

def task_func(MIN_WORDS, MAX_WORDS, WORDS_POOL):
    if MIN_WORDS < 0 or MAX_WORDS < MIN_WORDS:
        raise ValueError("Invalid word-count range.")

    words_pool = list(WORDS_POOL)
    word_count = random.randint(MIN_WORDS, MAX_WORDS)

    if word_count > 0 and not words_pool:
        raise ValueError("WORDS_POOL must not be empty.")

    first_half = [
        random.choice(words_pool)
        for _ in range((word_count + 1) // 2)
    ]

    palindrome_words = first_half + first_half[:word_count // 2][::-1]
    return " ".join(palindrome_words)

