import hashlib
import binascii


def task_func(salt, cursor):
    if not isinstance(salt, str):
        raise TypeError("salt must be a string")

    cursor.execute("SELECT rowid, password FROM users")
    users = cursor.fetchall()
    updated = 0

    for rowid, password in users:
        if isinstance(password, bytes):
            password_bytes = password
        else:
            password_bytes = str(password).encode("utf-8")

        salted_password = password_bytes + salt.encode("utf-8")
        hashed_password = binascii.hexlify(
            hashlib.sha256(salted_password).digest()
        ).decode("ascii")

        cursor.execute(
            "UPDATE users SET password = ? WHERE rowid = ?",
            (hashed_password, rowid),
        )
        updated += cursor.rowcount

    return updated

