def task_func(file_path1, file_path2, delimiter=',', quotechar='"'):
    try:
        with open(file_path1, 'r', encoding='utf-8', newline='') as file1:
            lines1 = file1.read().splitlines()

        with open(file_path2, 'r', encoding='utf-8', newline='') as file2:
            lines2 = file2.read().splitlines()
    except FileNotFoundError:
        raise
    except OSError as exc:
        raise Exception(f"Error reading CSV files: {exc}") from exc

    if not lines1 or not lines2:
        raise ValueError("Neither CSV file may be empty.")

