    line_number1 = 1
    line_number2 = 1

    for diff_line in ndiff(lines1, lines2):
        status = diff_line[:2]
        content = diff_line[2:]

        if status == '  ':
            differences.append({
                'Line Number': line_number1,
                'Status': ' ',
                'Content': content
            })
            line_number1 += 1
            line_number2 += 1
        elif status == '- ':
            differences.append({
                'Line Number': line_number1,
                'Status': '-',
                'Content': content
            })
            line_number1 += 1
        elif status == '+ ':
            differences.append({
                'Line Number': line_number2,
                'Status': '+',
                'Content': content
            })
            line_number2 += 1

    return pd.DataFrame(
        differences,
        columns=['Line Number', 'Status', 'Content']
    )

