def task_func(dictionary, item, sample_size=None, random_seed=None):
    """Return item positions and the DataFrame created from dictionary."""
    if sample_size is not None and (
        not isinstance(sample_size, int) or isinstance(sample_size, bool)
    ):
        raise TypeError("sample_size must be an integer or None")
    if sample_size is not None and sample_size < 0:
        raise ValueError("sample_size must be non-negative")

    dataframe = pd.DataFrame(dictionary)
    positions = []

    for row_index in range(len(dataframe)):
        for column_index, column_name in enumerate(dataframe.columns):
            value = dataframe.iloc[row_index, column_index]
            try:
                matches = bool(value == item)
            except (TypeError, ValueError):
                matches = False

            if matches:
                positions.append((row_index, column_name))

    if sample_size is not None:
        if random_seed is not None:
            seed(random_seed)

        sample_count = min(sample_size, len(positions))
        available = positions.copy()
        positions = []

        for _ in range(sample_count):
            position_index = randint(0, len(available) - 1)
            positions.append(available.pop(position_index))

