import itertools

def task_func(data_list, file_name):
    if not data_list:
        with open(file_name, "w") as file:
            pass
        return []

    columns = itertools.zip_longest(
        *(tuple(row[1:]) for row in data_list),
        fillvalue=np.nan
    )

    means = []
    for values in columns:
        numeric_values = []
        for value in values:
            try:
                if isinstance(value, str) or not np.isscalar(value):
                    raise ValueError
                numeric_values.append(value)
            except (TypeError, ValueError):
                numeric_values.append(np.nan)

        valid_values = np.asarray(numeric_values, dtype=float)
        valid_values = valid_values[~np.isnan(valid_values)]
        mean = np.mean(valid_values) if valid_values.size else np.nan
        means.append(mean)

    with open(file_name, "w") as file:
        for position, mean in enumerate(means, start=1):
            file.write(f"Position {position}: {mean}\n")

    return means

