    records = []
    start_time = time.time()

    while time.time() - start_time < duration:
        if platform.system() == "Windows":
            output = subprocess.check_output(
                "wmic cpu get loadpercentage",
                shell=True
            )
            text = output.decode(errors="replace")
            values = [
                float(token)
                for token in text.split()
                if token.replace(".", "", 1).isdigit()
            ]
            cpu_usage = values[-1] if values else 0.0
        else:
            output = subprocess.check_output("top -bn1", shell=True)
            text = output.decode(errors="replace")
            cpu_usage = 0.0

            for line in text.splitlines():
                if "Cpu(s)" in line or "%Cpu" in line:
                    parts = line.replace(",", ".").split()
                    for index, part in enumerate(parts):
                        if part.startswith("id"):
                            try:
                                idle = float(parts[index - 1])
                                cpu_usage = 100.0 - idle
                            except (ValueError, IndexError):
                                pass
                            break
                    break

        records.append({
            "timestamp": time.time(),
            "cpu_usage": cpu_usage
        })

        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as logfile:
            json.dump(records, logfile, indent=2)
    except IOError:
        return None

    return LOGFILE_PATH

