    for address in ip_addresses:
        if not isinstance(address, str):
            continue

        valid = False
        if re.fullmatch(r"[0-9a-fA-F:.]+", address):
            for family in (socket.AF_INET, socket.AF_INET6):
                try:
                    socket.inet_pton(family, address)
