import os
import re
import hashlib

def task_func(path, delimiter):
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    if not isinstance(delimiter, str):
        raise TypeError("delimiter must be a string")
    if delimiter == "":
        raise ValueError("delimiter must not be empty")

    parts = re.split(f"({re.escape(delimiter)})", path)
    components = []
    current = ""

    for part in parts:
        current += part
        if part == delimiter:
            components.append(current)
            current = ""

    if current or not components:
        components.append(current)

    result = []
    for component in components:
        component_hash = None
        if os.path.isfile(component):
            digest = hashlib.sha256()
            with open(component, "rb") as file:
                for chunk in iter(lambda: file.read(8192), b""):
                    digest.update(chunk)
            component_hash = digest.hexdigest()
        result.append((component, component_hash))

    return result

import pandas as pd
import itertools
import random

def task_func(colors, states):
    colors = list(colors)
    states = list(states)

    combinations = [
        f"{color}:{state}"
        for color, state in itertools.product(colors, states)
    ]
    random.shuffle(combinations)

    num_columns = min(len(colors), len(states))
    if num_columns == 0:
        return pd.DataFrame()

    base_size, remainder = divmod(len(combinations), num_columns)
    columns = {}
    start = 0

    for column_index in range(num_columns):
        chunk_size = base_size + (1 if column_index < remainder else 0)
        columns[column_index] = combinations[start:start + chunk_size]
        start += chunk_size

    return pd.DataFrame({
        column: pd.Series(values)
        for column, values in columns.items()
    })

