                    escaped = True
                elif char == '"':
                    in_string = False
                continue

            if char == '"':
                in_string = True
            elif char == "[":
                bracket_depth += 1
            elif char == "]":
                bracket_depth = max(0, bracket_depth - 1)

        pattern = re.compile(
            r'"name"\s*:\s*("(?:\\.|[^"\\])*")',
            re.IGNORECASE,
        )

        names = []
        for match in pattern.finditer(data):
            if depths[match.start()] == 0:
                names.append(json.loads(match.group(1)))

        return names
    except Exception:
        return "Invalid url input"

