def task_func(file_path='arena.csv', target_column='Index', seed=42):
    if not os.path.isfile(file_path):
        raise FileNotFoundError(f"File not found: {file_path}")

    data = pd.read_csv(file_path)

    if target_column not in data.columns:
        raise ValueError(
            f"Target column '{target_column}' was not found in the CSV file."
        )

    data = data.dropna()

    if data.empty:
        raise ValueError("Input data contains no valid rows after removing NaN values.")

    X = data.drop(columns=[target_column])
    y = data[target_column]

    if X.shape[1] == 0:
        raise ValueError("The input data must contain at least one feature column.")

    try:
        with np.errstate(over="ignore", invalid="ignore"):
            X_values = X.to_numpy(dtype=np.float32)
    except (TypeError, ValueError, OverflowError) as exc:
        raise ValueError(
            "Input data contains values that cannot be represented as float32."
        ) from exc

    if not np.isfinite(X_values).all():
        raise ValueError(
            "Input data contains NaN, infinity, or values too large for float32."
        )

    if pd.api.types.is_numeric_dtype(y):
        try:
            with np.errstate(over="ignore", invalid="ignore"):
                y_values = y.to_numpy(dtype=np.float32)
        except (TypeError, ValueError, OverflowError) as exc:
            raise ValueError(
                "Input data contains values that cannot be represented as float32."
            ) from exc

        if not np.isfinite(y_values).all():
            raise ValueError(
                "Input data contains NaN, infinity, or values too large for float32."
            )

    model = RandomForestClassifier(random_state=seed)
    model.fit(X_values, y)

    importances = model.feature_importances_

    fig, ax = plt.subplots()
    sns.barplot(
        x=importances,
        y=X.columns,
        orient="h",
        ax=ax,
    )
    ax.set_xlabel("Feature Importance")
    ax.set_ylabel("Feature")
    ax.set_title("Random Forest Feature Importances")
    fig.tight_layout()

    return ax, importances

