# Constants
TEAMS = ['Team A', 'Team B', 'Team C', 'Team D', 'Team E']
PENALTY_COST = 1000  # in dollars


def task_func(goals, penalties, rng_seed=None, teams=TEAMS):
    """Generate, analyze, and visualize football match results.

    Numeric scalar inputs are treated as maximum random values. Sequences
    provide one value per team. Goal strings may be scorelines such as '2-1'.
    """
    if rng_seed is not None:
        seed(rng_seed)

    teams = list(teams)
    if not teams:
        raise ValueError("teams must contain at least one team")

    def as_list(value, name):
        if isinstance(value, (int, float)):
            if value < 0 or int(value) != value:
                raise ValueError(f"{name} must be non-negative")
            return [randint(0, int(value)) for _ in teams]

        if isinstance(value, str):
            values = [value]
        else:
            try:
                values = list(value)
            except TypeError as exc:
                raise TypeError(f"{name} must be a number or iterable") from exc

        if len(values) != len(teams):
            raise ValueError(f"{name} must contain exactly {len(teams)} values")
        return values

    raw_goals = as_list(goals, "goals")
    raw_penalties = as_list(penalties, "penalties")

    goal_values = []
    match_results = []

    for result in raw_goals:
        if isinstance(result, str):
            numbers = re.findall(r"\d+", result)
            if not numbers:
                raise ValueError(f"Invalid match result: {result!r}")

            scored = int(numbers[0])
            if len(numbers) >= 2:
                opponent = int(numbers[1])
                original_result = result
            else:
                opponent = randint(0, max(scored, 5))
                original_result = f"{scored}-{opponent}"
        else:
            if not isinstance(result, (int, float)) or result < 0:
                raise ValueError("goals must contain non-negative numbers")
            if int(result) != result:
                raise ValueError("goals must contain whole numbers")
            scored = int(result)
            opponent = randint(0, max(scored, 5))
            original_result = f"{scored}-{opponent}"

        goal_values.append(scored)
        match_results.append(original_result)

    penalty_values = []
    for penalty in raw_penalties:
        if isinstance(penalty, str):
            numbers = re.findall(r"\d+", penalty)
            if not numbers:
                raise ValueError(f"Invalid penalty value: {penalty!r}")
            penalty = int(numbers[0])

        if not isinstance(penalty, (int, float)) or penalty < 0:
            raise ValueError("penalties must contain non-negative numbers")
        if int(penalty) != penalty:
            raise ValueError("penalties must contain whole numbers")
        penalty_values.append(int(penalty))

    data = pd.DataFrame({
        "Team": teams,
        "Goals": goal_values,
        "Penalty Cost": [count * PENALTY_COST for count in penalty_values],
        "Match Results": match_results,
    })

    ax = data.plot(
        x="Team",
        y=["Goals", "Penalty Cost"],
        kind="bar",
        figsize=(10, 6),
        title="Football Match Analysis",
    )
    ax.set_ylabel("Value")
    ax.set_xlabel("Team")
    plt.tight_layout()
    plt.show()
    plt.close(ax.figure)

    return data

from typing import List, Union
import numpy as np
import scipy.fft


def task_func(data: List[Union[int, str]], repetitions: int = 1):
    if not data or repetitions <= 0:
        return {
            "mode": np.array([]),
            "count": np.array([], dtype=int),
        }

    counts = {}
    for value in data:
        counts[value] = counts.get(value, 0) + 1

    maximum = max(counts.values())
    modes = [value for value, count in counts.items() if count == maximum]

    try:
        modes.sort()
    except TypeError:
        modes.sort(key=lambda value: (type(value).__name__, repr(value)))

    return {
        "mode": np.array(modes),
        "count": np.array([maximum * repetitions] * len(modes), dtype=int),
    }

import numpy as np
import pandas as pd
from numbers import Real


def task_func(
    products,
    n_samples=100,
    sales_lower=50,
    sales_upper=200,
    profit_margin_min=0.1,
    profit_margin_max=0.5,
    random_seed=42,
):
    if not isinstance(products, list) or not all(
        isinstance(product, str) for product in products
    ):
        raise TypeError("products must be a list of strings")

    if not isinstance(n_samples, (int, np.integer)) or isinstance(n_samples, bool):
        raise ValueError("n_samples must be a positive integer")
    if n_samples <= 0:
        raise ValueError("n_samples must be a positive integer")

    numeric_values = (
        sales_lower,
        sales_upper,
        profit_margin_min,
        profit_margin_max,
    )
    if not all(isinstance(value, Real) and not isinstance(value, bool)
               for value in numeric_values):
        raise TypeError("sales and profit parameters must be numeric")

    if sales_lower > sales_upper:
        raise ValueError("sales_lower cannot be greater than sales_upper")

    np.random.seed(random_seed)
    rows = []

    for product in products:
        if float(sales_lower).is_integer() and float(sales_upper).is_integer():
            sales = np.random.randint(
                int(sales_lower),
                int(sales_upper) + 1,
                size=n_samples,
            )
        else:
            sales = np.random.uniform(
                sales_lower,
                sales_upper,
                size=n_samples,
            )

        margins = np.random.uniform(
            profit_margin_min,
            profit_margin_max,
            size=n_samples,
        )
        profits = sales * margins

        rows.append(
            {
                "Product": product,
                "Total Sales": sales.sum(),
                "Total Profit": profits.sum(),
            }
        )

    return (
        pd.DataFrame(rows, columns=["Product", "Total Sales", "Total Profit"])
        .sort_values("Total Profit", ascending=False)
        .reset_index(drop=True)
    )

