    for module_info in iter_modules(package_paths):
        module_names.append(module_info.name)

        module_path = getattr(module_info.module_finder, "path", None)
        if module_path:
            module_path = os.fspath(module_path)
            if module_path not in added_paths and module_path not in sys.path:
                sys.path.append(module_path)
                added_paths.add(module_path)

    return module_names

