import heapq
from scipy import stats


def task_func(df, col1, col2, N=10):
    if col1 not in df.columns or col2 not in df.columns:
        raise ValueError("Specified columns are not in the provided DataFrame.")

    if N <= 1:
        raise ValueError("N must be greater than 1.")

    differences = [
        (abs(value1 - value2), value1, value2)
        for value1, value2 in zip(df[col1], df[col2])
    ]

    largest = heapq.nlargest(N, differences, key=lambda item: item[0])
    values1 = [item[1] for item in largest]
    values2 = [item[2] for item in largest]

    return float(stats.ttest_ind(values1, values2).pvalue)

