import re
import pandas as pd
from datetime import datetime
import os


def task_func(log_file):
    pattern = re.compile(
        r"^(?P<type>[^:\r\n]+): \[(?P<timestamp>[^\]\r\n]*)\] - (?P<message>.*)$"
    )
    entries = []

    with open(log_file, "r", encoding="utf-8") as file:
        for line in file:
            line = line.rstrip("\r\n")
            match = pattern.match(line)

            if not match:
                continue

            timestamp = match.group("timestamp")
            if not re.fullmatch(
                r"\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}", timestamp
            ):
                raise ValueError("Invalid timestamp in log entry")

            try:
                datetime.strptime(timestamp, "%Y-%m-%d %H:%M:%S")
            except ValueError as exc:
                raise ValueError("Invalid timestamp in log entry") from exc

            entries.append(
                {
                    "Type": match.group("type"),
                    "Timestamp": timestamp,
                    "Message": match.group("message"),
                }
            )

    if not entries:
        raise ValueError("No valid log entries found")

    output_file = os.path.splitext(log_file)[0] + ".csv"
    pd.DataFrame(entries, columns=["Type", "Timestamp", "Message"]).to_csv(
        output_file, index=False
    )

    return output_file

