import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt

# Constants
HEADERS = {
    'accept': 'application/json'
}


def task_func(url, parameters):
    """
    Retrieve API data, convert it to a DataFrame, and display a correlation
    heatmap for its numerical characteristics.

    Returns:
        tuple: (pandas.DataFrame, matplotlib.axes.Axes)

    Raises:
        Exception: If the URL is invalid, inaccessible, the response is empty,
                   or the returned data is invalid.
    """
    try:
        if not isinstance(url, str) or not url.strip():
            raise Exception("The URL must be a non-empty string.")

        response = requests.get(
            url,
            params=parameters,
            headers=HEADERS,
            timeout=30
        )
        response.raise_for_status()

        if not response.content:
            raise Exception("The API returned empty data.")

        try:
            data = response.json()
        except (ValueError, json.JSONDecodeError) as exc:
            raise Exception("The API returned invalid JSON data.") from exc

        if data is None or data == [] or data == {}:
            raise Exception("The API returned empty data.")

        if isinstance(data, dict):
            if "data" in data:
                data = data["data"]
            elif "results" in data:
                data = data["results"]

        if not isinstance(data, (list, dict)):
            raise Exception("The API returned invalid data.")

        dataframe = pd.DataFrame(data)

        if dataframe.empty:
            raise Exception("The API returned empty data.")

        numeric_data = dataframe.select_dtypes(include="number")
        if numeric_data.empty:
            raise Exception("The data contains no numerical characteristics.")

        correlation = numeric_data.corr()
        axes = sns.heatmap(correlation, annot=True, cmap="coolwarm")
        plt.show()

        return dataframe, axes

    except Exception as exc:
        if isinstance(exc, Exception) and str(exc):
            raise Exception(str(exc)) from exc
        raise Exception("Unable to retrieve or process the API data.") from exc

import random
import re

def task_func(text, seed=None):
    rng = random.Random(seed)

    def scramble(match):
        word = match.group(0)
        if len(word) <= 3:
            return word

        middle = list(word[1:-1])
        rng.shuffle(middle)
        return word[0] + "".join(middle) + word[-1]

    return re.sub(r"\b\w+\b", scramble, text)

import subprocess
import os
import time
import glob

def task_func(r_script_path: str, output_path: str, duration: int) -> (bool, str):
    success_message = "File generated successfully within the specified duration."
    failure_message = "File not generated within the specified duration."

    try:
        process = subprocess.Popen(["Rscript", r_script_path])
    except (OSError, subprocess.SubprocessError):
        return False, failure_message

    start_time = time.monotonic()

    try:
        while time.monotonic() - start_time <= max(0, duration):
            matching_paths = glob.glob(output_path)

            if any(os.path.isfile(path) for path in matching_paths):
                return True, success_message

            if process.poll() is not None and duration <= 0:
                break

            time.sleep(0.05)
    finally:
        if process.poll() is None:
            process.terminate()
            try:
                process.wait(timeout=1)
            except subprocess.TimeoutExpired:
                process.kill()
                process.wait()

    return False, failure_message

