import pandas as pd
import os


def task_func(f_list, file_path):
    if not isinstance(f_list, list) or not f_list:
        raise ValueError("f_list must be a non-empty list of functions")

    if not all(inspect.isfunction(function) for function in f_list):
        raise ValueError("f_list must contain only functions")

    try:
        path = os.fspath(file_path)
        if not isinstance(path, (str, bytes)) or not path:
            raise ValueError("file_path must be a valid path")

        if isinstance(path, str) and "\x00" in path:
            raise ValueError("file_path must be a valid path")

        absolute_path = os.path.abspath(path)
        if not os.path.basename(absolute_path) or os.path.isdir(absolute_path):
            raise ValueError("file_path must be a valid file path")

        parent_directory = os.path.dirname(absolute_path)
        if not os.path.isdir(parent_directory):
            raise ValueError("file_path must point to an existing directory")
    except (TypeError, ValueError, OSError) as exc:
        if isinstance(exc, ValueError):
            raise
        raise ValueError("file_path must be a valid path") from exc

    rows = []
    for function in f_list:
        signature = inspect.signature(function)
        defaults = {
            parameter.name: parameter.default
            for parameter in signature.parameters.values()
            if parameter.default is not inspect.Parameter.empty
        }

        rows.append(
            {
                "Function Name": function.__name__,
                "Number of Arguments": len(signature.parameters),
                "Defaults": defaults,
                "Annotations": function.__annotations__,
                "Is Lambda": function.__name__ == "<lambda>",
            }
        )

    dataframe = pd.DataFrame(
        rows,
        columns=[
            "Function Name",
            "Number of Arguments",
            "Defaults",
            "Annotations",
            "Is Lambda",
        ],
    )

