import rsa
import urllib.request
from hashlib import sha256
import urllib.error


def task_func(url):
    public_key, private_key = rsa.newkeys(2048)

    try:
        with urllib.request.urlopen(url) as response:
            content = response.read()
    except urllib.error.HTTPError as exc:
        raise ValueError(f"HTTP error while retrieving URL: {exc}") from exc
    except urllib.error.URLError:
        raise
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError(f"Unable to retrieve URL: {exc}") from exc

    content_hash = sha256(content).digest()

    try:
        signed_hash = rsa.sign_hash(content_hash, private_key, "SHA-256")
    except rsa.pkcs1.VerificationError:
        raise
    except Exception as exc:
        raise rsa.pkcs1.VerificationError(str(exc)) from exc

    return public_key, signed_hash.hex(), content_hash

