import os
import shutil

def task_func(path, delimiter="/"):
    if not isinstance(path, str) or not path:
        raise ValueError("path must be a non-empty string")

    if not isinstance(delimiter, str) or not delimiter:
        raise ValueError("delimiter must be a non-empty string")

    if "\x00" in path or not os.path.exists(path):
        if "\x00" in path:
            raise ValueError("path contains an invalid component")
        raise FileNotFoundError(path)

    raw_components = path.split(delimiter)
    absolute = path.startswith(delimiter)

    if absolute:
        raw_components = raw_components[1:]

    if raw_components and raw_components[-1] == "":
        raw_components.pop()

    if any(component in ("", ".", "..") or "\x00" in component
           for component in raw_components):
        raise ValueError("path contains invalid components")

    drive, _ = os.path.splitdrive(path)
    current = drive + os.sep if drive and absolute else delimiter if absolute else ""

    result = []
    for component in raw_components:
        current = os.path.join(current, component)
        usage = shutil.disk_usage(current)
        result.append((
            component,
            {
                "total": usage.total,
                "used": usage.used,
                "free": usage.free,
            },
        ))

    return result

