import subprocess
import psutil
import time
import os


def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script not found: {script_path}")

    process = subprocess.Popen(["bash", script_path])
    monitored = psutil.Process(process.pid)

    cpu_usage = 0.0
    memory_usage = 0
    start_time = time.monotonic()
    cpu_initialized = False

    try:
        while True:
            elapsed = time.monotonic() - start_time
            remaining = timeout - elapsed

            if remaining <= 0:
                if process.poll() is None:
                    process.terminate()
                    try:
                        process.wait(timeout=1)
                    except subprocess.TimeoutExpired:
                        process.kill()
                        process.wait()
                break

            if process.poll() is not None:
                break

            interval = min(0.1, remaining)

            try:
                if not cpu_initialized:
                    monitored.cpu_percent(None)
                    cpu_initialized = True

                cpu_usage += monitored.cpu_percent(interval=interval)

                if monitored.status() != psutil.STATUS_ZOMBIE:
                    memory_usage += monitored.memory_info().rss
            except (psutil.NoSuchProcess, psutil.ZombieProcess):
                break

        if process.poll() is None:
            process.wait()
    finally:
        if process.poll() is None:
            process.terminate()
            try:
                process.wait(timeout=1)
            except subprocess.TimeoutExpired:
                process.kill()
                process.wait()

    return {
        "CPU Usage": cpu_usage,
        "Memory Usage": memory_usage,
    }

