from collections import Counter
# Constants
REPLACE_NONE = "None"

def task_func(json_str):
    email_pattern = re.compile(
        r"\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b"
    )

    def process(value):
        if value is None:
            return None
        if isinstance(value, dict):
            return {
                key: processed
                for key, item in value.items()
                if (processed := process(item)) is not None
            }
        if isinstance(value, list):
            return [
                processed
                for item in value
                if (processed := process(item)) is not None
            ]
        if isinstance(value, str):
            return email_pattern.sub(REPLACE_NONE, value)
        return value

    def collect_values(value, counts):
        if isinstance(value, dict):
            for item in value.values():
                collect_values(item, counts)
        elif isinstance(value, list):
            for item in value:
                collect_values(item, counts)
        else:
            try:
                counts[value] += 1
            except TypeError:
                pass

    data = process(json.loads(json_str))
    value_counts = Counter()
    collect_values(data, value_counts)

    return {
        "data": data,
        "value_counts": value_counts,
    }

