import os
import re
from pathlib import Path


def task_func(dir_path: str, predicates: list) -> dict:
    """
    Evaluate each directory item's name against the supplied predicates.

    String predicates are treated as regular expressions. Callable predicates
    receive the item name. Duplicate valid predicates are evaluated once.
    """
    directory = Path(dir_path)
    if not directory.is_dir():
        raise FileNotFoundError(
            f"Specified directory does not exist or is not a directory: {dir_path}"
        )

    valid_predicates = []
    seen = set()

    for predicate in predicates:
        normalized = None

        if isinstance(predicate, str):
            if not predicate:
                continue
            try:
                normalized = ("regex", predicate, 0, re.compile(predicate))
            except re.error:
                continue
        elif isinstance(predicate, re.Pattern):
            normalized = (
                "regex",
                predicate.pattern,
                predicate.flags,
                predicate,
            )
        elif callable(predicate):
            try:
                hash(predicate)
                key = ("callable", predicate)
            except TypeError:
                key = ("callable", id(predicate))

            if key in seen:
                continue
            seen.add(key)
            valid_predicates.append(predicate)
            continue

        if normalized is not None:
            key = normalized[:3]
            if key not in seen:
                seen.add(key)
                valid_predicates.append(normalized[3])

    if not valid_predicates:
        raise ValueError("No valid predicates were provided.")

    result = {}
    for item_name in os.listdir(directory):
        checks = []
        for predicate in valid_predicates:
            if isinstance(predicate, re.Pattern):
                checks.append(bool(predicate.search(item_name)))
            else:
                checks.append(bool(predicate(item_name)))
        result[item_name] = checks

    return result

