        extension = "." + extension

    if os.path.abspath(src_dir) == os.path.abspath(dest_dir):
        return {"files_moved": 0}

    os.makedirs(dest_dir, exist_ok=True)
    files_moved = 0

    for filename in os.listdir(src_dir):
        source_path = os.path.join(src_dir, filename)

        if os.path.isfile(source_path) and filename.endswith(extension):
            shutil.move(source_path, os.path.join(dest_dir, filename))
            files_moved += 1

    return {"files_moved": files_moved}

import random
import re

def task_func(target_words, n_sentences, vocabulary):
    if n_sentences < 0:
        raise ValueError("n_sentences must be non-negative")
    if not vocabulary:
        raise ValueError("vocabulary must not be empty")

    patterns = []
    for target in target_words:
        escaped = re.escape(str(target)).replace(r"\ ", r"\s+")
        patterns.append(escaped)

    pattern = None
    if patterns:
        pattern = re.compile(
            r"(?<!\w)(?:" + "|".join(sorted(patterns, key=len, reverse=True)) + r")(?!\w)",
            re.IGNORECASE,
        )

    sentences = []
    for _ in range(n_sentences):
        words = random.choices(vocabulary, k=10)
        sentence = " ".join(map(str, words)).lower()

        if pattern is not None:
            sentence = pattern.sub(lambda match: match.group(0).replace(" ", "_"), sentence)

        sentences.append(sentence)

    return sentences

