import ast
import re


def task_func(text_file: str) -> list:
    with open(text_file, "r", encoding="utf-8") as file:
        text = file.read()

    dictionaries = []

    for match in re.finditer(r"\{", text):
        start = match.start()
        depth = 0
        quote = None
        escaped = False

        for index in range(start, len(text)):
            char = text[index]

            if quote:
                if escaped:
                    escaped = False
                elif char == "\\":
                    escaped = True
                elif char == quote:
                    quote = None
                continue

            if char in ("'", '"'):
                quote = char
            elif char == "{":
                depth += 1
            elif char == "}":
                depth -= 1
                if depth == 0:
                    try:
                        value = ast.literal_eval(text[start:index + 1])
                        if isinstance(value, dict):
                            dictionaries.append(value)
                    except (SyntaxError, ValueError):
                        pass
                    break

    return dictionaries

