def task_func(excel_directory: str, file_name: str, column_name: str, start_date: str, end_date: str) -> pd.DataFrame:
    file_path = os.path.join(excel_directory, file_name)

    if not os.path.isfile(file_path):
        raise FileNotFoundError(f"Excel file not found: {file_path}")

    try:
        start = datetime.strptime(start_date, "%Y-%m-%d")
        end = datetime.strptime(end_date, "%Y-%m-%d")
    except (TypeError, ValueError) as exc:
        raise ValueError("Dates must be in the YYYY-MM-DD format.") from exc

    dataframe = pd.read_excel(file_path)

    if column_name not in dataframe.columns:
        raise ValueError(f"Column does not exist: {column_name}")

    dates = pd.to_datetime(dataframe[column_name], errors="coerce")
    mask = (dates >= start) & (dates <= end)

    return dataframe.loc[mask].copy()

