            writable = [client for client in clients if pending_data.get(client)]
            exceptional = list(clients) + [server_socket]
            timeout = max(0, (deadline - datetime.now()).total_seconds())

            try:
                ready_read, ready_write, ready_exceptional = select.select(
                    readable, writable, exceptional, timeout
                )
            except (OSError, ValueError):
                break

            if server_socket in ready_exceptional:
                break

            if server_socket in ready_read:
                try:
                    client_socket, _ = server_socket.accept()
                    client_socket.setblocking(False)
                    clients.add(client_socket)
                    pending_data[client_socket] = queue.Queue()
                except (OSError, ValueError):
                    pass

            for client_socket in list(ready_exceptional):
                if client_socket is server_socket:
                    continue
                clients.discard(client_socket)
                pending_data.pop(client_socket, None)
                try:
                    client_socket.close()
                except OSError:
                    pass

            for client_socket in list(ready_read):
                if client_socket is server_socket or client_socket not in clients:
                    continue

                try:
                    data = client_socket.recv(buffer_size)
                    if not data:
                        raise ConnectionError
                    response = data + str(datetime.now()).encode()
                    pending_data[client_socket].put(response)
                except (OSError, ConnectionError, ValueError):
                    clients.discard(client_socket)
                    pending_data.pop(client_socket, None)
                    try:
                        client_socket.close()
                    except OSError:
                        pass

            for client_socket in list(ready_write):
                if client_socket not in clients:
                    continue

                try:
                    output_queue = pending_data[client_socket]
                    data = output_queue.get_nowait()
                    sent = client_socket.send(data)
                    if sent < len(data):
                        remaining = data[sent:]
                        replacement = queue.Queue()
                        replacement.put(remaining)
                        while True:
                            try:
                                replacement.put(output_queue.get_nowait())
                            except queue.Empty:
                                break
                        pending_data[client_socket] = replacement
                except queue.Empty:
                    pass
                except (OSError, ValueError):
                    clients.discard(client_socket)
                    pending_data.pop(client_socket, None)
                    try:
                        client_socket.close()
                    except OSError:
                        pass
    finally:
        for client_socket in list(clients):
            try:
                client_socket.close()
            except OSError:
                pass
        try:
            server_socket.close()
        except OSError:
            pass

    return f"Echo server ran for {run_duration} seconds."

import pandas as pd
