import datetime


def task_func(start_year=1980, end_year=2000, email_domain='example.com',
              latin_names=['Sopetón', 'Méndez', 'Gómez', 'Pérez', 'Muñoz'],
              other_names=['Smith', 'Johnson', 'Williams', 'Brown', 'Jones'],
              rng_seed=None):
    if start_year > end_year:
        raise ValueError("start_year must not exceed end_year")
    if not latin_names and not other_names:
        raise ValueError("At least one name must be provided")
    if start_year < 0 or end_year > 9999:
        raise ValueError("Years must be between 0 and 9999")

    def correct_encoding(name):
        if isinstance(name, bytes):
            name = name.decode("utf-8", errors="replace")

        name = str(name)
        try:
            repaired = name.encode("latin1").decode("utf-8")
            if "Ã" in name or "Â" in name or "â" in name:
                return repaired
        except (UnicodeEncodeError, UnicodeDecodeError):
            pass
        return name

    names = [correct_encoding(name) for name in latin_names + other_names]
    rng = np.random.default_rng(rng_seed)

    selected_names = rng.choice(names, size=100)

    dates = []
    for _ in range(100):
        year = int(rng.integers(start_year, end_year + 1))
        month = int(rng.integers(1, 13))

        if month in (4, 6, 9, 11):
            days_in_month = 30
        elif month == 2:
            leap = year % 400 == 0 or (year % 4 == 0 and year % 100 != 0)
            days_in_month = 29 if leap else 28
        else:
            days_in_month = 31

        day = int(rng.integers(1, days_in_month + 1))

        if year == 0:
            date_value = f"{year:04d}-{month:02d}-{day:02d} 00:00:00"
        else:
            date_value = datetime.datetime(year, month, day)

        dates.append((date_value, year))

    data = []
    for record_id, (name, (date_value, birth_year)) in enumerate(
        zip(selected_names, dates), start=1
    ):
        email = f"{name.lower()}{birth_year}@{email_domain}"
        data.append({
            "ID": record_id,
            "Name": name,
            "Date of Birth": date_value,
            "Email": email,
        })

    return pd.DataFrame(data, columns=["ID", "Name", "Date of Birth", "Email"])

