import pandas as pd
import numpy as np
from statsmodels.tsa.seasonal import seasonal_decompose


def task_func(start_date='2016-01-01', periods=24, freq='M', model='additive'):
    if not isinstance(periods, (int, np.integer)) or periods <= 0:
        raise ValueError("periods must be a positive integer")

    if model not in {'additive', 'multiplicative'}:
        raise ValueError("model must be either 'additive' or 'multiplicative'")

    frequency = str(freq).upper()
    if frequency.startswith(('M',)):
        seasonal_period = 12
    elif frequency.startswith(('Q',)):
        seasonal_period = 4
    elif frequency.startswith(('W',)):
        seasonal_period = 52
    elif frequency.startswith(('D',)):
        seasonal_period = 7
    elif frequency.startswith(('H',)):
        seasonal_period = 24
    elif frequency.startswith(('T', 'MIN')):
        seasonal_period = 60
    elif frequency.startswith(('S',)):
        seasonal_period = 60
    else:
        seasonal_period = 12

    if periods < 2 * seasonal_period:
        raise ValueError(
            f"periods must be at least {2 * seasonal_period} for frequency '{freq}'"
        )

    dates = pd.date_range(start=start_date, periods=periods, freq=freq)
    time = np.arange(periods, dtype=float)
    rng = np.random.default_rng(42)

    trend = 100 + 1.5 * time
    seasonal_pattern = 1 + 0.2 * np.sin(2 * np.pi * time / seasonal_period)
    noise = rng.normal(0, 0.03, periods)

    if model == 'multiplicative':
        sales = trend * seasonal_pattern * (1 + noise)
    else:
        sales = trend + 15 * np.sin(2 * np.pi * time / seasonal_period) + rng.normal(
            0, 3, periods
        )

    sales_series = pd.Series(sales, index=dates, name='sales')
    decomposition = seasonal_decompose(
        sales_series,
        model=model,
        period=seasonal_period,
        extrapolate_trend=False,
    )

    return {
        'trend': decomposition.trend,
        'seasonal': decomposition.seasonal,
        'residual': decomposition.resid,
    }

