import csv
import collections


def task_func(csv_file, emp_prefix='EMP$$'):
    """Count records for each employee in a CSV file."""
    close_file = False

    if isinstance(csv_file, (str, bytes)):
        csv_file = open(csv_file, newline='', encoding='utf-8')
        close_file = True

    try:
        rows = list(csv.reader(csv_file))
    finally:
        if close_file:
            csv_file.close()

    if not rows:
        return {}

    employee_headers = {
        'employee',
        'employee_id',
        'employeeid',
        'emp',
        'emp_id',
        'empid',
    }

    first_row = [cell.strip() for cell in rows[0]]
    header_index = next(
        (
            index
            for index, value in enumerate(first_row)
            if value.lower().replace(' ', '_') in employee_headers
        ),
        None,
    )

    if header_index is not None:
        data_rows = rows[1:]
    else:
        header_index = 0
        data_rows = rows

    counts = collections.Counter()

    for row in data_rows:
        if header_index < len(row):
            employee = row[header_index].strip()
            if employee.startswith(emp_prefix):
                counts[employee] += 1

    return dict(counts)

