import json
import os
import re


def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},
            "age": {"type": int},
            "email": {"type": str}
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"
):
    if not os.path.isfile(file_path):
        raise ValueError(f"File does not exist: {file_path}")

    try:
        with open(file_path, "r", encoding="utf-8") as file:
            data = json.load(file)
    except (OSError, json.JSONDecodeError) as error:
        raise ValueError("Unable to read or parse the JSON file") from error

    expected_root_type = INPUT_JSON.get("type")
    if expected_root_type is not None and not isinstance(data, expected_root_type):
        raise ValueError("JSON root type does not match the schema")

    properties = INPUT_JSON.get("properties", {})
    required = INPUT_JSON.get("required", [])

    for field in required:
        if field not in data:
            raise ValueError(f"Required attribute is missing: {field}")

    for field, rules in properties.items():
        if field not in data:
            continue

        expected_type = rules.get("type")
        if expected_type is not None:
            value = data[field]
            if expected_type is int and isinstance(value, bool):
                raise ValueError(f"Attribute has an invalid type: {field}")
            if not isinstance(value, expected_type):
                raise ValueError(f"Attribute has an invalid type: {field}")

    if "email" in data:
        if not isinstance(data["email"], str) or re.fullmatch(
            EMAIL_REGEX, data["email"]
        ) is None:
            raise ValueError("Invalid email format")

    if attribute not in data:
        raise ValueError(f"Attribute is missing: {attribute}")

    return data[attribute]

