        elif isinstance(value, dict):
            latitude = value.get("latitude", value.get("lat"))
            longitude = value.get("longitude", value.get("lon"))
        else:
            try:
                if len(value) >= 2:
                    latitude, longitude = value[0], value[1]
            except (TypeError, IndexError):
                continue

        try:
            latitude = float(latitude)
            longitude = float(longitude)
            if pd.isna(latitude) or pd.isna(longitude):
                continue
        except (TypeError, ValueError):
            continue

        locations.append((name, latitude, longitude))

    if locations:
        center = [
            sum(location[1] for location in locations) / len(locations),
            sum(location[2] for location in locations) / len(locations),
        ]
    else:
        center = [0, 0]

    result_map = folium.Map(location=center, zoom_start=2)

    for name, latitude, longitude in locations:
        folium.Marker(
            location=[latitude, longitude],
            popup=str(name),
        ).add_to(result_map)

