import numpy as np
import random
from datetime import datetime
from datetime import timedelta


def task_func(
    rows=3,
    columns=2,
    start_date=datetime(2021, 1, 1),
    end_date=datetime(2021, 12, 31),
    seed=0,
):
    if isinstance(rows, bool) or not isinstance(rows, (int, np.integer)):
        raise TypeError("rows must be an integer")
    if isinstance(columns, bool) or not isinstance(columns, (int, np.integer)):
        raise TypeError("columns must be an integer")
    if rows < 0 or columns < 0:
        raise ValueError("rows and columns must be non-negative")
    if not isinstance(start_date, datetime) or not isinstance(end_date, datetime):
        raise TypeError("start_date and end_date must be datetime objects")
    if end_date < start_date:
        raise ValueError("end_date must not be earlier than start_date")

    total = rows * columns
    available_dates = (end_date - start_date).days + 1

    if total > available_dates:
        raise ValueError("the date range does not contain enough unique dates")

    rng = random.Random(seed)
    offsets = rng.sample(range(available_dates), total)
    dates = [start_date + timedelta(days=offset) for offset in offsets]

    return np.array(dates, dtype=object).reshape(rows, columns)

