import http.server
import smtplib
from email.mime.text import MIMEText
import json


def task_func(smtp_server, smtp_port, smtp_username, smtp_password):
    class EmailRequestHandler(http.server.BaseHTTPRequestHandler):
        def _send_response(self, status_code, message):
            body = json.dumps({"message": message}).encode("utf-8")
            self.send_response(status_code)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def do_POST(self):
            try:
                content_length = int(self.headers.get("Content-Length", "0"))
                raw_data = self.rfile.read(content_length)
                email_data = json.loads(raw_data.decode("utf-8"))

                if not isinstance(email_data, dict):
                    raise ValueError("Email data must be a JSON object")

                required_keys = {"subject", "message", "to"}
                if not required_keys.issubset(email_data):
                    raise ValueError("Missing required email fields")

                email = MIMEText(str(email_data["message"]), "plain", "utf-8")
                email["Subject"] = str(email_data["subject"])
                email["From"] = smtp_username
                email["To"] = str(email_data["to"])

                smtp = None
                try:
                    smtp = smtplib.SMTP(smtp_server, smtp_port)
                    smtp.login(smtp_username, smtp_password)
                    smtp.sendmail(
                        smtp_username,
                        str(email_data["to"]),
                        email.as_string(),
                    )
                except smtplib.SMTPAuthenticationError:
                    self._send_response(535, "Authentication Failed")
                    return
                finally:
                    if smtp is not None:
                        try:
                            smtp.quit()
                        except Exception:
                            pass

                self._send_response(200, "Email sent successfully")

            except json.JSONDecodeError:
                self._send_response(400, "Invalid JSON")
            except ValueError as exc:
                self._send_response(400, str(exc))

    return EmailRequestHandler

