import pandas as pd
from datetime import datetime

# Constants
ROOMS = ["Room1", "Room2", "Room3", "Room4", "Room5"]


def task_func(date_str, booking_data):
    """Generate a room-booking status report and bar plot for a date."""
    if not isinstance(date_str, str):
        raise ValueError("date_str must use the yyyy-mm-dd format")

    try:
        requested_date = datetime.strptime(date_str, "%Y-%m-%d").date()
    except (TypeError, ValueError):
        raise ValueError("date_str must use the yyyy-mm-dd format")

    if requested_date < datetime.now().date():
        raise ValueError("date_str cannot refer to a past date")

    def normalize_status(value):
        if isinstance(value, bool):
            return "Booked" if value else "Available"
        if value is None:
            return "Booked"
        return str(value)

    def matching_date(value):
        if isinstance(value, datetime):
            return value.date() == requested_date
        if hasattr(value, "date") and not isinstance(value, str):
            return value.date() == requested_date
        return str(value) == date_str

    statuses = {room: "Available" for room in ROOMS}

    if isinstance(booking_data, pd.DataFrame):
        records = booking_data.to_dict("records")
    elif isinstance(booking_data, (list, tuple)):
        records = booking_data
    elif isinstance(booking_data, dict):
        records = None

        if date_str in booking_data:
            dated_bookings = booking_data[date_str]
            if isinstance(dated_bookings, dict):
                for room in ROOMS:
                    if room in dated_bookings:
                        statuses[room] = normalize_status(dated_bookings[room])
            else:
                for room in ROOMS:
                    if room in dated_bookings:
                        statuses[room] = "Booked"

        for room in ROOMS:
            if room in booking_data and isinstance(booking_data[room], dict):
                room_bookings = booking_data[room]
                if date_str in room_bookings:
                    statuses[room] = normalize_status(room_bookings[date_str])

        if records is None:
            records = []
    else:
        records = []

    for record in records:
        if not isinstance(record, dict):
            continue

        room = record.get("room", record.get("room_name"))
        booking_date = record.get(
            "date",
            record.get("booking_date", record.get("bookingDate")),
        )

        if room not in ROOMS or not matching_date(booking_date):
            continue

        status = record.get(
            "status",
            record.get("booking_status", record.get("bookingStatus")),
        )
        statuses[room] = normalize_status(status)

    report = pd.DataFrame(
        [{"Room": room, "Status": statuses[room]} for room in ROOMS]
    )

    import matplotlib.pyplot as plt

    status_counts = report["Status"].value_counts()
    ax = status_counts.plot(
        kind="bar",
        title=f"Booking Status for {date_str}",
        xlabel="Status",
        ylabel="Number of Rooms",
    )
    plt.tight_layout()

    return report, ax

