import pandas as pd
from itertools import cycle
from random import randint, seed


def task_func(
    n_grades,
    students=['Alice', 'Bob', 'Charlie', 'David', 'Eve'],
    grade_range=range(1, 11),
    rng_seed=None
):
    if not students:
        raise ValueError("List of students cannot be empty")

    if rng_seed is not None:
        seed(rng_seed)

    student_cycle = cycle(students)
    grades = [
        {
            "Student": next(student_cycle),
            "Grade": randint(min(grade_range), max(grade_range)),
        }
        for _ in range(n_grades)
    ]

    return pd.DataFrame(grades, columns=["Student", "Grade"])

import ipaddress
import requests


def task_func(ip_range, timeout):
    try:
        network = ipaddress.ip_network(ip_range, strict=False)
    except (ValueError, TypeError) as exc:
        raise ValueError("Invalid IP range") from exc

    active_ips = []

    for ip in network.hosts():
        try:
            response = requests.get(f"http://{ip}", timeout=timeout)
            if response.status_code == 200:
                active_ips.append(str(ip))
        except requests.RequestException:
            continue

    return active_ips

