import re
import math

def task_func(s):
    number_pattern = re.compile(
        r"^[+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+]?\d+)?$"
    )

    numbers = []
    for item in s.split(","):
        value = item.strip()
        if number_pattern.fullmatch(value):
            numbers.append(float(value))

    return len(numbers), sum(math.sqrt(number) for number in numbers)

