import pandas as pd
from sklearn.preprocessing import LabelEncoder


def task_func(df, dct, columns=None):
    if not isinstance(df, pd.DataFrame):
        raise ValueError("df must be a pandas DataFrame")

    result = df.copy()
    result.replace(dct, inplace=True)

    if columns is None:
        categorical_columns = list(
            result.select_dtypes(include=["object", "category"]).columns
        )
    elif isinstance(columns, str):
        categorical_columns = [columns]
    else:
        categorical_columns = list(columns)

    for column in categorical_columns:
        encoder = LabelEncoder()
        result[column] = encoder.fit_transform(result[column])

    numerical_columns = result.select_dtypes(include="number").columns
    numerical_columns = [
        column for column in numerical_columns
        if column not in categorical_columns
    ]

    for column in numerical_columns:
        result[column] = (
            result[column] - result[column].mean()
        ) / result[column].std()

    return result

import subprocess
import psutil
import time


def task_func(process_name: str) -> str:
    processes = [
        process
        for process in psutil.process_iter(["name"])
        if process.info.get("name") == process_name
    ]

    if not processes:
        subprocess.Popen(process_name, shell=True)
        return f"Process not found. Starting {process_name}."

    for process in processes:
        try:
            process.terminate()
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            continue

    _, alive = psutil.wait_procs(processes, timeout=3)
    for process in alive:
        try:
            process.kill()
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            pass

    time.sleep(0.1)
    subprocess.Popen(process_name, shell=True)
    return f"Process found. Restarting {process_name}."

