from collections import Counter
import re

def task_func(word: str) -> list:
    cleaned_word = re.sub(r"[^a-z]", "", word.lower())

    if len(cleaned_word) < 2:
        return []

    combinations = [
        cleaned_word[i:i + 2]
        for i in range(len(cleaned_word) - 1)
    ]

    most_common_combination, frequency = Counter(combinations).most_common(1)[0]
    return [(most_common_combination, frequency)]

