import os
import re
import shutil

def task_func(source_directory: str, target_directory: str, pattern: str = r"\d{4}") -> int:
    if not os.path.isdir(source_directory):
        return 0

    os.makedirs(target_directory, exist_ok=True)
    regex = re.compile(pattern)
    moved_count = 0

    for filename in os.listdir(source_directory):
        source_path = os.path.join(source_directory, filename)

        if not os.path.isfile(source_path) or not regex.search(filename):
            continue

        target_path = os.path.join(target_directory, filename)

        try:
            shutil.move(source_path, target_path)
            moved_count += 1
        except (OSError, shutil.Error):
            continue

    return moved_count

import time
import threading

def task_func(delay_time: float = 1.0, num_threads: int = 5):
    messages = [None] * num_threads

    def delay_and_complete(thread_index: int) -> None:
        time.sleep(delay_time)
        messages[thread_index] = f"Delay in thread {thread_index} completed"

    threads = [
        threading.Thread(target=delay_and_complete, args=(index,))
        for index in range(num_threads)
    ]

    for thread in threads:
        thread.start()

    for thread in threads:
        thread.join()

    return messages

