import requests
import logging


def task_func(repo_url: str) -> dict:
    try:
        response = requests.get(repo_url, timeout=10)
        response.raise_for_status()

        try:
            repository_info = response.json()
        except (ValueError, TypeError) as exc:
            raise requests.exceptions.RequestException(
                "The GitHub API returned an invalid JSON response."
            ) from exc

        if not isinstance(repository_info, dict):
            raise requests.exceptions.RequestException(
                "The GitHub API response is not a repository object."
            )

        open_issues = repository_info.get("open_issues_count", 0)
        if isinstance(open_issues, int) and open_issues > 1000:
            logging.warning(
                "Repository has a large number of open issues: %s",
                open_issues,
            )

        return repository_info

    except requests.exceptions.HTTPError:
        logging.exception("GitHub API HTTP error for %s", repo_url)
        raise
    except requests.exceptions.RequestException:
        logging.exception("GitHub API request failed for %s", repo_url)
        raise

