# Constants
LETTERS = ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j']


def task_func(n_keys, n_values):
    """Create a dictionary with random letter keys and consecutive integer values."""
    if n_keys < 0 or n_keys > len(LETTERS):
        raise ValueError(f"n_keys must be between 0 and {len(LETTERS)}")
    if n_values < 0:
        raise ValueError("n_values must be non-negative")

    result = collections.defaultdict(list)
