import seaborn as sns
import pandas as pd

# Constants
COLUMNS = ['A', 'B', 'C', 'D', 'E']


def task_func(df: pd.DataFrame, tuples: list, n_plots: int) -> (pd.DataFrame, list):
    """Remove matching rows and generate random joint plots."""
    rows_to_remove = pd.Series(False, index=df.index)

    for values in tuples:
        if len(values) != len(COLUMNS):
            raise ValueError(
                f"Each tuple must contain exactly {len(COLUMNS)} values."
            )

        matches = pd.Series(True, index=df.index)
        for column, value in zip(COLUMNS, values):
            matches &= df[column].eq(value)

        rows_to_remove |= matches

    modified_df = df.loc[~rows_to_remove].copy()
    plots = []

    if not modified_df.empty:
        for _ in range(n_plots):
            x_column, y_column = sample(COLUMNS, 2)
            plots.append(
                sns.jointplot(
                    data=modified_df,
                    x=x_column,
                    y=y_column,
                )
            )

    return modified_df, plots

