import json
import os

# Constants
PREFIXES = ["is_", "has_", "can_", "should_"]


def task_func(directory):
    """Count keys beginning with each configured prefix in JSON files."""
    statistics = {prefix: 0 for prefix in PREFIXES}

    def count_keys(value):
        if isinstance(value, dict):
            for key, nested_value in value.items():
                if isinstance(key, str):
                    for prefix in PREFIXES:
                        if key.startswith(prefix):
                            statistics[prefix] += 1
                count_keys(nested_value)
        elif isinstance(value, list):
            for item in value:
                count_keys(item)

    for filename in os.listdir(directory):
        path = os.path.join(directory, filename)
        if os.path.isfile(path) and filename.lower().endswith(".json"):
            with open(path, "r", encoding="utf-8") as file:
                count_keys(json.load(file))

    return statistics

from datetime import datetime
import pandas as pd

# For Python versions lower than 3.9, use 'pytz' instead of 'zoneinfo'
try:
    from zoneinfo import ZoneInfo
except ImportError:
    from pytz import timezone as ZoneInfo

TIME_FORMAT = "%d/%m/%y %H:%M:%S.%f"


def task_func(time_strings, target_tz):
    target_timezone = ZoneInfo(target_tz)
    converted_times = []

    for time_string in time_strings:
        utc_time = datetime.strptime(time_string, TIME_FORMAT).replace(
            tzinfo=ZoneInfo("UTC")
        )
        converted_times.append(
            utc_time.astimezone(target_timezone).strftime(TIME_FORMAT)
        )

    return pd.DataFrame(
        {
            "Original Time": time_strings,
            "Converted Time": converted_times,
        }
    )

